import org.apache.druid.query.spec.QuerySegmentSpecs;
import org.apache.druid.segment.TestHelper;
import org.junit.Assert;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;

public class ZZDebugCacheTest
{
  @Test
  public void testRoundTrip() throws Exception
  {
    GroupByQuery query = GroupByQuery
        .builder()
        .setDataSource(Druids.DataSource.withDefault("ds"))
        .setQuerySegmentSpec(QuerySegmentSpecs.create("2011-01-12/2011-01-14"))
        .setDimensions(Collections.singletonList(new org.apache.druid.query.dimension.DefaultDimensionSpec("test", "test")))
        .setAggregatorSpecs(Arrays.asList(new CountAggregatorFactory("cnt")))
        .setPostAggregatorSpecs(
            Arrays.asList(
                new ConstantPostAggregator("post", 10),
                new ConstantPostAggregator("post2", 20),
                new ConstantPostAggregator("post3", 30)
            )
        )
        .setGranularity(Granularities.DAY)
        .build();

    CacheStrategy<org.apache.druid.query.groupby.ResultRow, Object, GroupByQuery> strategy =
        new GroupByQueryQueryToolChest(null).getCacheStrategy(query);

    ResultRow row = ResultRow.of(123L, "val1", 1, 10, 20, 30);
    Object prepared = strategy.prepareForCache(true).apply(row);
    System.out.println("PREPARED: " + prepared);

    ObjectMapper mapper = TestHelper.makeJsonMapper();
    byte[] bytes = mapper.writeValueAsBytes(prepared);
    System.out.println("JSON: " + new String(bytes));

    Object fromCache = mapper.readValue(bytes, strategy.getCacheObjectClazz());
    System.out.println("FROM CACHE: " + fromCache);

    ResultRow pulled = strategy.pullFromCache(true).apply(fromCache);
    System.out.println("PULLED: " + pulled);
    Assert.assertEquals(row, pulled);
  }
}

